// CloudtainerML rev0030 — Expert-choice sparse attention frontier.
// Tiny synthetic probe inspired by MoSA and LoLA: content/head-specific sparse token choice
// versus local windows, sparse cache, and dense attention under an iso-cost score.
#include <bits/stdc++.h>
using namespace std;
static string q(const string&s){string o="\""; for(char c:s){if(c=='\"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o+'\"';}
struct Regime{string name; double head_specialization, locality, recurrence, rare_needles, noise, clusteriness; int seed;};
struct Row{string regime,method; int n,heads,budget; double recall,error,cost_frac,head_collision,tail_miss,cache_staleness,regret,score;};
static double clamp01(double x){return max(0.0,min(1.0,x));}
static double noisehash(int a,int b,int c){uint64_t x=1469598103934665603ULL; x^=a+0x9e3779b97f4a7c15ULL; x*=1099511628211ULL; x^=b*1315423911u; x*=1099511628211ULL; x^=c*2654435761u; x*=1099511628211ULL; return ((x>>11)&((1ULL<<53)-1))*1.1102230246251565e-16;}
static Row eval(const Regime&r,string m,int N,int H,int bp){double B=bp/100.0; double base_need=0.36+0.38*r.rare_needles+0.22*r.head_specialization; double recall=0,cost=0,coll=0,tail=0,stale=0;
 if(m=="dense_attention"){recall=0.995-0.04*r.noise; cost=1.0; coll=0.02; tail=0.0;}
 else if(m=="uniform_sparse"){recall=clamp01(B*(0.80+0.10*r.locality)-0.24*r.rare_needles+0.05*r.clusteriness); cost=B+0.02; coll=0.42*r.head_specialization; tail=0.62*r.rare_needles;}
 else if(m=="cluster_routing"){recall=clamp01(0.24+0.82*B+0.28*r.clusteriness-0.30*r.rare_needles-0.14*r.noise); cost=B+0.07; coll=0.26*(1-r.clusteriness)+0.18*r.head_specialization; tail=0.38*r.rare_needles;}
 else if(m=="mosa_expert_choice"){recall=clamp01(0.28+0.92*B+0.36*r.head_specialization+0.16*r.clusteriness-0.18*r.noise-0.18*r.recurrence); cost=B+0.11; coll=0.08*(1+r.noise); tail=0.18*r.rare_needles;}
 else if(m=="lola_sparse_cache"){recall=clamp01(0.20+0.65*B+0.45*r.recurrence+0.20*r.locality-0.20*r.head_specialization-0.12*r.noise); cost=B*0.72+0.08; stale=0.22*(1-r.recurrence)+0.18*r.noise; tail=0.35*r.rare_needles*(1-r.recurrence); coll=0.14;}
 else { // hybrid_mosa_lola
   double rm=clamp01(0.28+0.78*B+0.28*r.head_specialization+0.16*r.clusteriness-0.13*r.noise);
   double rl=clamp01(0.18+0.56*B+0.48*r.recurrence+0.18*r.locality-0.16*r.noise);
   recall=clamp01(0.62*rm+0.42*rl+0.08*min(r.head_specialization,r.recurrence)); cost=B*0.86+0.14; coll=0.08; stale=0.10*(1-r.recurrence); tail=0.14*r.rare_needles; }
 recall=clamp01(recall + 0.015*(noisehash(r.seed,N,H)-0.5)); double error=max(0.0,base_need-recall); double over=max(0.0,cost-B); double score=error + 0.42*over + 0.18*coll + 0.28*tail + 0.12*stale + 0.03*cost; return {r.name,m,N,H,bp,recall,error,cost,coll,tail,stale,0,score};}
int main(int argc,char**argv){string outp=argc>1?argv[1]:"REV0030_EXPERT_CHOICE_SPARSE_ATTENTION_SMOKE.json"; vector<Regime> regs={{"head_specialized_syntax",.92,.25,.20,.28,.08,.35,1},{"local_recurrent_story",.35,.88,.82,.18,.12,.55,2},{"rare_needle_alias",.65,.18,.28,.96,.16,.22,3},{"clustered_topics",.52,.38,.48,.28,.14,.90,4},{"noisy_flat_context",.25,.22,.20,.30,.65,.18,5}}; vector<string> ms={"dense_attention","uniform_sparse","cluster_routing","mosa_expert_choice","lola_sparse_cache","hybrid_mosa_lola"}; vector<Row> rows; map<string,int>wins,non; for(auto&r:regs) for(int N:{128,512,2048}) for(int H:{4,8,16}) for(int bp:{12,20,32,50}){vector<Row> cand; for(auto&m:ms)cand.push_back(eval(r,m,N,H,bp)); double best=1e9; for(auto&x:cand)best=min(best,x.score); for(auto&x:cand){x.regret=max(0.0,x.score-best); rows.push_back(x);} auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); wins[b->method]++; auto nb=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="dense_attention")return false; if(b.method=="dense_attention")return true; return a.score<b.score;}); non[nb->method]++;}
 ofstream f(outp); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0030\",\n  \"probe\": \"expert_choice_sparse_attention\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:non){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Expert-choice sparse attention only matters when head specialization or rare token routing offsets overhead; LoLA-style sparse cache helps recurrent regimes but can stale on rare needles.\",\n    \"screen_regret_fields\": [\"recall\",\"error\",\"cost_frac\",\"head_collision\",\"tail_miss\",\"cache_staleness\",\"regret\",\"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"n\": "<<r.n<<", \"heads\": "<<r.heads<<", \"budget_pct\": "<<r.budget<<", \"recall\": "<<r.recall<<", \"error\": "<<r.error<<", \"cost_frac\": "<<r.cost_frac<<", \"head_collision\": "<<r.head_collision<<", \"tail_miss\": "<<r.tail_miss<<", \"cache_staleness\": "<<r.cache_staleness<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1<rows.size()?",":"")<<"\n";} f<<"  ]\n}\n";}
